ruleBookInfo.name:
@js:
if (/\/posts\/[^/?#]+/.test(String(baseUrl))) {
  java.getString("tag.h1@text");
} else {
  java.getString("tag.header@tag.a.0@text");
}

ruleBookInfo.coverUrl:
@js:
var src = "";
if (/\/posts\/[^/?#]+/.test(String(baseUrl))) {
  src = String(java.getString("tag.article@tag.img@src") || "");
}
if (src && src.charAt(0) === "/") {
  src = String(baseUrl).replace(/^(https?:\/\/[^/]+).*$/, "$1") + src;
}
src;

ruleToc.chapterName:
@js:
var title = java.getString("tag.h2@tag.a@text");
if (!title) title = java.getString("text");
String(title || "");

ruleToc.chapterUrl:
@js:
var href = String(java.getString("tag.h2@tag.a@href") || "");
if (!href) href = String(baseUrl || "");
if (href.charAt(0) === "/") {
  href = String(baseUrl).replace(/^(https?:\/\/[^/]+).*$/, "$1") + href;
}
href;

ruleToc.nextTocUrl:
@js:
var href = "";
var nodes = java.getElements("tag.a");
var total = nodes.size ? nodes.size() : nodes.length;
for (var i = 0; i < total; i++) {
  var node = nodes.get ? nodes.get(i) : nodes[i];
  java.setContent(node);
  var text = String(java.getString("text") || "");
  if (text.indexOf("下一页") >= 0) {
    href = String(java.getString("href") || "");
    break;
  }
}
if (href && href.charAt(0) === "/") {
  href = String(baseUrl).replace(/^(https?:\/\/[^/]+).*$/, "$1") + href;
}
href;
